-- The status tick also lists a cancelled invoice whose storno is not yet sent.
CREATE OR REPLACE FUNCTION "app"."tenants_due_invoice_status"()
RETURNS TABLE (tenant_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
AS $$
  select distinct i.tenant_id
  from app.invoices as i
  where i.state in ('created', 'cancelling')
     or (i.state = 'cancelled' and i.storno_sent = false and i.storno_number is not null)
$$;